    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which federal program provides health insurance primarily for individuals aged 65 and older, as well as younger people with certain disabilities?', '["Medicaid", "Medicare", "CHIP", "TRICARE"]', 1, 'Medicare is the federal health insurance program for seniors and certain younger people with disabilities or End-Stage Renal Disease.'),
    (v_topic_id, 'Which federal-state partnership program provides health coverage for low-income individuals and families?', '["Medicare", "Medicaid", "HMO", "PPO"]', 1, 'Medicaid is a needs-based program that provides health coverage for low-income Americans, including children, pregnant women, and people with disabilities.'),
    (v_topic_id, 'Medicare Part A primarily covers which of the following?', '["Outpatient doctor visits", "Hospital stays, skilled nursing facility care, and hospice", "Prescription drugs", "Dental and vision care"]', 1, 'Medicare Part A is hospital insurance. Part B covers outpatient services, and Part D covers prescription drugs.'),
    (v_topic_id, 'Which part of Medicare covers outpatient services, including physician visits and medical equipment?', '["Part A", "Part B", "Part C", "Part D"]', 1, 'Medicare Part B is medical insurance for outpatient services and preventative care.'),
    (v_topic_id, 'A "Health Maintenance Organization" (HMO) typically requires patients to:', '["See any doctor they want", "Choose a Primary Care Physician (PCP) and obtain referrals to see specialists", "Pay higher monthly premiums than a PPO", "Only see doctors in other states"]', 1, 'HMOs emphasize coordinated care through a PCP and generally only cover services within their network (except for emergencies).'),
    (v_topic_id, 'In a "Preferred Provider Organization" (PPO), patients:', '["Must stay within a small network", "Can see any provider they choose, but pay less if they stay within the ''preferred'' network", "Are not covered for emergency care", "Must get a referral for every appointment"]', 1, 'PPOs offer more flexibility but often have higher premiums or deductibles than HMOs.'),
    (v_topic_id, 'Which federal law requires emergency departments to stabilize and treat anyone regardless of their ability to pay or insurance status?', '["HIPAA", "EMTALA", "COBRA", "ERISA"]', 1, 'The Emergency Medical Treatment and Labor Act (EMTALA) prevents "patient dumping" by requiring hospitals to provide a screening exam and stabilizing treatment to all patients in the ED.'),
    (v_topic_id, 'A "Sentinel Event" in a hospital must be followed by which of the following processes to identify system failures?', '["A disciplinary hearing for the individual involved", "A Root Cause Analysis (RCA)", "A lawsuit", "A press conference"]', 1, 'RCA is a structured method used to analyze serious adverse events to identify the underlying "systems" issues rather than just blaming individuals.'),
    (v_topic_id, 'The concept of "Triage" in a mass casualty incident prioritizes patients based on:', '["Who arrived first", "The severity of their condition and their likelihood of survival with immediate intervention", "Who has the best insurance", "Social status"]', 1, 'Triage aims to do the "greatest good for the greatest number" when resources are overwhelmed.'),
    (v_topic_id, 'Under the "Rule of Rescue," society feels a strong moral obligation to:', '["Save the most lives possible in a future disaster", "Save an identified person whose life is currently in immediate danger, even if the cost is extremely high", "Provide free care to everyone", "None of the above"]', 1, 'The Rule of Rescue reflects a psychological tendency to prioritize immediate, visible life-saving efforts over preventative or statistical life-saving.'),
    (v_topic_id, 'A hospital uses "Crisis Standards of Care" during a severe pandemic. This means the ethical focus shifts from:', '["Utilitarianism to Deontology", "Patient-centered care (Autonomy) to Community-centered care (maximizing overall survival)", "Beneficence to Non-maleficence", "None of the above"]', 1, 'During a crisis, resource allocation becomes utilitarian, focusing on saving the maximum number of people with limited supplies.'),
    (v_topic_id, 'Which term describes the payment model where a physician is paid a set amount per patient per month, regardless of how many services the patient uses?', '["Fee-for-Service", "Capitation", "Value-Based Care", "Pay-for-Performance"]', 1, 'Capitation shifts the financial risk to the provider and encourages preventative care and efficiency.'),
    (v_topic_id, 'In a "Fee-for-Service" model, the primary incentive for the physician is to:', '["Provide as few services as possible", "Provide more services, as each service generates a separate payment", "Focus only on preventative care", "None of the above"]', 1, 'Fee-for-service can lead to over-utilization of healthcare resources.'),
    (v_topic_id, 'Which program provides health insurance to children in families with incomes too high to qualify for Medicaid but too low to afford private insurance?', '["Medicare", "CHIP (Children''s Health Insurance Program)", "TRICARE", "COBRA"]', 1, 'CHIP is a vital part of the safety net for children''s health in the US.'),
    (v_topic_id, 'The "Hospice" benefit under Medicare is available to patients who:', '["Have any chronic illness", "Have a terminal illness with a life expectancy of 6 months or less, as certified by two physicians", "Are over the age of 85", "Are currently in the ICU"]', 1, 'Hospice focuses on comfort care rather than curative treatment at the end of life.'),
    (v_topic_id, 'A "Value-Based Care" model rewards providers for:', '["The volume of patients they see", "Improved patient outcomes and quality of care, often with lower overall costs", "Using the most expensive technology", "Working the most hours"]', 1, 'Value-based care aims to align financial incentives with the quality and efficiency of healthcare.'),
    (v_topic_id, 'The "Iron Triangle" of healthcare refers to the trade-offs between which three factors?', '["Doctors, Nurses, and Patients", "Cost, Access, and Quality", "Research, Education, and Clinical Care", "Insurance, Government, and Hospitals"]', 1, 'Improving one vertex of the Iron Triangle (e.g., increasing access) often puts pressure on the others (e.g., increasing cost or decreasing quality).'),
    (v_topic_id, 'A physician receives a "Bonus" for meeting certain quality metrics, such as the percentage of their diabetic patients with controlled HbA1c. This is:', '["Capitation", "Pay-for-Performance (P4P)", "Fee-for-Service", "None of the above"]', 1, 'P4P models aim to improve specific clinical outcomes.'),
    (v_topic_id, 'Which federal agency is responsible for overseeing the Medicare and Medicaid programs?', '["CDC", "CMS (Centers for Medicare & Medicaid Services)", "FDA", "NIH"]', 1, 'CMS is a part of the Department of Health and Human Services (HHS).'),
    (v_topic_id, 'An "Accountable Care Organization" (ACO) is:', '["A group of doctors and hospitals that collaborate to provide coordinated, high-quality care to their Medicare patients", "A type of insurance company", "A medical board that disciplines doctors", "None of the above"]', 0, 'ACOs aim to ensure that patients get the right care at the right time while avoiding unnecessary duplication of services.'),
    (v_topic_id, 'A patient is "Discharged" from the hospital while they are still medically unstable because their insurance company refuses to pay for more days. This is a violation of:', '["EMTALA (if they weren''t stabilized)", "The physician''s duty to the patient (Non-maleficence/Beneficence)", "Both A and B", "Neither"]', 2, 'Financial considerations should not dictate unsafe clinical discharges.'),
    (v_topic_id, 'The "DRG" (Diagnosis-Related Group) system is used by Medicare to pay hospitals a:', '["Fixed amount based on the patient''s diagnosis, regardless of the actual cost of care during that stay", "Fee for every single pill and bandage used", "Percentage of the hospital''s total budget", "Bonus for every patient discharged early"]', 0, 'DRGs encourage hospitals to be efficient and avoid unnecessary costs.'),
    (v_topic_id, 'Which term describes a patient''s out-of-pocket cost that must be paid before their insurance starts to cover services?', '["Co-payment", "Deductible", "Premium", "Co-insurance"]', 1, 'Deductibles can be a significant barrier to accessing care for some patients.'),
    (v_topic_id, 'A "Co-payment" is:', '["A monthly fee to have insurance", "A fixed amount (e.g., $20) paid by the patient at the time of service", "A percentage of the total bill", "The total cost of a surgery"]', 1, 'Copays are a form of cost-sharing.'),
    (v_topic_id, '"Co-insurance" is:', '["A fixed amount paid at the visit", "The percentage of the medical bill (e.g., 20%) that the patient is responsible for paying after the deductible is met", "The monthly insurance fee", "None of the above"]', 1, 'Coinsurance splits the cost of care between the insurer and the patient.'),
    (v_topic_id, 'A "Premium" in health insurance is:', '["The highest quality of care", "The amount paid (usually monthly) to purchase the insurance policy", "The total amount the insurance company pays out", "A bonus for healthy patients"]', 1, 'Premiums are the cost of maintaining coverage.'),
    (v_topic_id, 'Which federal law allows employees to continue their health insurance coverage for a limited time after leaving a job (at their own expense)?', '["HIPAA", "COBRA", "ERISA", "EMTALA"]', 1, 'COBRA (Consolidated Omnibus Budget Reconciliation Act) provides a safety net during job transitions.'),
    (v_topic_id, 'A physician "Upcodes" a patient''s visit (billing for a more complex service than was actually provided) to increase reimbursement. This is:', '["Good business", "Fraud and a violation of veracity/justice", "Allowed if the patient is wealthy", "None of the above"]', 1, 'Upcoding is illegal and unethical.'),
    (v_topic_id, '"Unbundling" in medical billing refers to:', '["Giving a patient a discount", "Billing separately for multiple components of a procedure that should be billed as a single, all-inclusive code", "Grouping many patients together", "None of the above"]', 1, 'Unbundling is a form of billing fraud.'),
    (v_topic_id, 'Which of the following is a key goal of "Population Health Management"?', '["Seeing as many patients as possible per hour", "Improving the health outcomes of an entire group of individuals by addressing social determinants of health and using data analytics", "Only treating sick people", "None of the above"]', 1, 'Population health looks at the broad factors that influence health across a community.'),
    (v_topic_id, 'The "Social Determinants of Health" include:', '["Genetic mutations", "Economic stability, education, neighborhood environment, and social support", "Only biological factors", "None of the above"]', 1, 'Non-medical factors (like housing and food security) significantly impact health outcomes.'),
    (v_topic_id, 'A "Safety-Net" hospital is one that:', '["Has the best trauma center", "Provides a significant amount of care to low-income, uninsured, and vulnerable populations, regardless of their ability to pay", "Is only for government employees", "None of the above"]', 1, 'Safety-net providers are essential for health equity.'),
    (v_topic_id, 'A patient is denied a life-saving medication by their insurance company because it is "off-label" or too expensive. This is a conflict between:', '["Individual Beneficence and System Justice/Resource Allocation", "Autonomy and Veracity", "Fidelity and Privacy", "None of the above"]', 0, 'Resource allocation decisions often create tension between the needs of the individual and the constraints of the system.'),
    (v_topic_id, 'The "Quality-Adjusted Life Year" (QALY) is a measure used in cost-effectiveness analysis that combines:', '["The patient''s age and weight", "The quantity (years) and quality (health status) of life gained from an intervention", "The cost of the drug and the doctor''s time", "None of the above"]', 1, 'QALYs are controversial but widely used in health policy to compare the value of different treatments.'),
    (v_topic_id, 'A triage officer in a disaster assigns a "Black Tag" to a patient who is still alive but has unsalvageable injuries. The goal of this difficult decision is to:', '["Punish the patient", "Allocate limited life-saving resources (like surgeons and oxygen) to patients who have a better chance of survival", "Save money", "None of the above"]', 1, 'This is a core utilitarian decision in disaster medicine.'),
    (v_topic_id, 'Which principle is most directly involved in "Organ Allocation" (deciding who gets a heart or liver transplant)?', '["Autonomy", "Distributive Justice", "Non-maleficence", "Veracity"]', 1, 'Justice requires a fair and transparent system for distributing extremely scarce and life-saving organs.'),
    (v_topic_id, 'The "United Network for Organ Sharing" (UNOS) in the US manages organ allocation based on factors like:', '["Ability to pay", "Medical urgency, time on the waiting list, and geographic proximity", "Social importance", "Religious beliefs"]', 1, 'The UNOS system aims to be objective and equitable.'),
    (v_topic_id, 'A physician refers all their patients to an imaging center that the physician personally owns. This is a:', '["Great way to ensure quality", "Conflict of interest and potentially a violation of the ''Stark Law'' (Self-Referral)", "Required by insurance", "None of the above"]', 1, 'Self-referral laws prevent physicians from profiting from their own referrals, which could bias their medical judgment.'),
    (v_topic_id, 'The "Kickback" refers to:', '["A patient paying their bill late", "A physician receiving a payment or gift from a company (like a drug rep) in exchange for using or promoting their product", "A nurse getting a bonus", "None of the above"]', 1, 'Kickbacks are illegal and compromise the physician''s objectivity (Fidelity to the patient).'),
    (v_topic_id, 'A "Patient-Centered Medical Home" (PCMH) is a care delivery model where:', '["The patient lives in the clinic", "A team-led by a PCP-provides comprehensive, coordinated, and accessible care for the ''whole'' patient", "Only home visits are allowed", "None of the above"]', 1, 'PCMH aims to improve the quality and experience of primary care.'),
    (v_topic_id, 'Which term describes the phenomenon where having insurance makes a person more likely to use healthcare services, sometimes unnecessarily?', '["Adverse Selection", "Moral Hazard", "Risk Adjustment", "Capitation"]', 1, 'Moral hazard is an economic concept relevant to insurance design (e.g., use of copays to minimize it).'),
    (v_topic_id, '"Adverse Selection" occurs when:', '["The doctor chooses the wrong medicine", "Individuals who are more likely to need healthcare (the ''sickest'') are the ones most likely to buy insurance, potentially making it unaffordable for others", "The insurance company goes bankrupt", "None of the above"]', 1, 'Insurance markets need a mix of healthy and sick people to remain stable.'),
    (v_topic_id, 'A "High-Deductible Health Plan" (HDHP) is often paired with which type of tax-advantaged savings account?', '["IRA", "HSA (Health Savings Account)", "401k", "529 Plan"]', 1, 'HSAs allow patients to save money tax-free for their out-of-pocket medical expenses.'),
    (v_topic_id, 'Which of the following is a component of "Quality Improvement" (QI) in a hospital?', '["Reducing medical errors", "Decreasing wait times in the ED", "Improving patient satisfaction scores", "All of the above"]', 3, 'QI is an ongoing, systematic effort to improve the processes and outcomes of healthcare.'),
    (v_topic_id, 'The "PDSA" cycle in Quality Improvement stands for:', '["Practice, Deliver, Support, Analyze", "Plan, Do, Study, Act", "Patient, Doctor, Staff, Administration", "None of the above"]', 1, 'The PDSA cycle is a standard tool for testing and implementing small changes to improve systems.'),
    (v_topic_id, 'A "Near Miss" in patient safety is:', '["A patient almost dying", "An error that occurred but was caught before it reached the patient, causing no harm", "A surgery that was slightly late", "None of the above"]', 1, 'Reporting and analyzing near misses is essential to prevent actual harm in the future.'),
    (v_topic_id, '"Just Culture" in a hospital encourages:', '["Blaming the individual for every mistake", "Reporting errors and near misses by focusing on system flaws rather than punishing individuals for human errors, while still holding them accountable for reckless behavior", "Ignoring all mistakes", "None of the above"]', 1, 'Just culture balances accountability with a systems-thinking approach to safety.'),
    (v_topic_id, 'A "Never Event" is:', '["Something that happens every day", "A serious, largely preventable patient safety incident that should never occur (e.g., wrong-site surgery)", "A rare disease", "A patient who never pays"]', 1, 'Never events are often used as quality benchmarks and may result in non-payment from insurers.'),
    (v_topic_id, 'Which healthcare system is characterized by being government-funded and government-run (e.g., the Veterans Affairs system in the US)?', '["Bismarck Model", "Beveridge Model (Socialized Medicine)", "National Health Insurance Model", "Out-of-Pocket Model"]', 1, 'The VA is the closest US equivalent to a socialized healthcare system like the UK''s NHS.'),
    (v_topic_id, 'The "Bismarck Model" (used in Germany and Japan) uses:', '["Only government doctors", "Private insurers (''sickness funds'') that are non-profit and tightly regulated, with universal coverage funded through employer/employee payroll taxes", "No insurance at all", "None of the above"]', 1, 'Most employer-based insurance in the US has some elements of the Bismarck model but is for-profit and not universal.');
